・終点は「保安対象物件の外壁又はこれに相当する工作物の外側」
・つまり敷地の境界線からではなく、建物どうしの外側どうしを結んだ距離です
・敷地の内側にある自分の会社の建物や住居は原則として対象外（同一敷地内の住居は除かれる）★
