━━━━━━━━━━━━━━━━━━━━━━
・条文は具体的な勾配の数値を定めず「適当な傾斜」とだけ書いています
・これは施設の規模や取り扱う危険物の粘度によって適正な勾配が変わるためです
・重油のように粘度の高いものは緩い勾配では流れないので、より急な傾斜が必要になります
・試験では「傾斜は100分の1以上でなければならない」のような具体的数値を出してくる誤り選択肢に注意★

