　対象｜すべての製造所等（必要な範囲で）｜蒸気・微粉が滞留するおそれのある建築物★
　排出先｜特に定めなし｜屋外の高所★
　動力｜自然換気でもよい｜強制排気が基本
　給気口の位置｜低い位置または適宜｜低所（蒸気は下にたまるため）★
