・具体的には防爆型の照明器具・スイッチ・コンセントを使用する
・スイッチは室外に設けるのが実務上の原則。室内でスイッチを入れた瞬間の火花が着火源になり得るからです
・裸電球や白熱灯は表面温度が高く、可燃性蒸気の発火点を超えることがあるため使用しない
・懐中電灯も防爆型のものを使用する

