━━━━━━━━━━━━━━━━━━━━━━
・換気は室内の空気を入れ替えるので、換気だけでは床にたまった重い蒸気は抜けません
・そのため排出設備は床面近くから吸い込むように設計します
・換気扇のモーターも、可燃性蒸気が滞留するおそれのある場所では防爆型を用います
・タンク内部の清掃など、蒸気濃度が高くなる作業では強制換気を行い、濃度を測定してから入槽します

