━━━━━━━━━━━━━━━━━━━━━━
・蒸気は重いので、低い位置に出すと地面を這って遠くまで流れます
・流れた先にボイラーや車のエンジンがあれば、そこで着火して炎が逆流してきます（フラッシュバック）★
・高所に出せば、蒸気は大気中で希釈され、燃焼下限界未満になってから地面に降りてきます
・「屋外」が抜けて「屋内の高所」となっている選択肢、「高所」が抜けて「屋外」だけの選択肢の両方に注意★

