・ピットや排水溝には蒸気がたまるので、開放型にせず、たまった液は随時くみ上げる
・可燃性蒸気が滞留するおそれのある場所では、火花を発する機械器具・工具・履物を使用しない★
・電線と電気器具は完全に接続し、接触不良による火花を防ぐ★
・静電気靴（導電性の靴）を履かせるのは、静電気を逃がすためであり、火花を防ぐためでもあります

