　空気をイオン化する（除電器）｜空気中のイオンで電荷を中和する｜
　導電性の作業服・靴を用いる｜人体の帯電を防ぐ｜
　配管の先端を液中に入れる（底部注入）｜落下による噴出帯電を防ぐ｜
