・ガソリンを携行缶に入れるときは、缶を地面（コンクリート）に置いて注ぎます。車の荷台に載せたまま入れるとタイヤが絶縁体となって電荷が逃げません★
・ノズルの先端を容器の内壁に沿わせ、液面下に入れることで、飛沫と噴出帯電を抑えます
・注ぐ速度を遅くする、途中で止めずに一気に注ぐ、といった作業手順も静電気対策の一部です

