━━━━━━━━━━━━━━━━━━━━━━
・移動貯蔵タンクの下部に排出口を設ける場合は、その排出口に底弁を設けること★
・底弁には、非常時にタンクの直近で閉鎖できる手動閉鎖装置と、自動閉鎖装置を設けること★
