・保安距離も保有空地も取れません。だから「距離」ではなく「構造と運用」で安全を確保します★
・具体的には、車が安全に停まって給油できる広さ（給油空地）、こぼれた油を受け止める舗装と貯留設備、周囲を守る塀、そしてエンジン停止のルールです
・数字の主役は「間口10m以上・奥行6m以上」の給油空地です★
