・貯留設備または油分離装置にたまった危険物は、あふれないように随時くみ上げること★
・危険物のくず、かす等は、1日に1回以上、当該危険物の性質に応じて安全な場所および方法で廃棄その他適当な処置をすること★
・危険物を貯蔵し、または取り扱う建築物その他の工作物または設備は、当該危険物の性質に応じ、遮光または換気を行うこと★
・危険物は、温度計、湿度計、圧力計その他の計器を監視して、当該危険物の性質に応じた適正な温度、湿度または圧力を保つように貯蔵し、または取り扱うこと★
・危険物を貯蔵し、または取り扱う場合においては、当該危険物が漏れ、あふれ、または飛散しないように必要な措置を講ずること★
・危険物を容器に収納して貯蔵し、または取り扱うときは、その容器は危険物の性質に適応し、かつ、破損、腐食、裂け目等がないものであること★
・危険物を収納した容器を貯蔵し、または取り扱う場合は、みだりに転倒させ、落下させ、衝撃を加え、または引きずる等粗暴な行為をしないこと★
