　人の出入り｜係員以外はみだりに出入りさせない★｜
　整理清掃｜常に行い不必要な物件を置かない★｜
　たまった危険物｜あふれないよう随時くみ上げる★｜
　くず・かす｜1日1回以上処置★｜
　温度等｜計器を監視して適正に保つ★｜
　容器｜性質に適応し破損腐食裂け目がないもの★｜
　容器の扱い｜転倒落下衝撃引きずりを避ける★｜
　保護液｜危険物を露出させない★｜

