・水が微生物を繁殖させ、その代謝物が局所的な腐食（微生物腐食）を起こすこともあります
・冬季に水が凍ると、体積が膨張して配管や弁を破壊します
・水が混じった燃料をボイラーや車に供給すると、失火や機器の損傷につながります

━━━━━━━━━━━━━━━━━━━━━━
