・下水に流せば、下水道の中で蒸気がたまって爆発します。実際にそういう事故が起きています
・地面に撒けば土壌と地下水を汚し、川に流せば魚が死に、火がつけば水面を火が走ります
・そこで法令は「捨て方」まで細かく決めました
