・容器の種類には、内装容器と外装容器（内装容器を収納する外側の容器）がある
・機械により荷役する構造を有する運搬容器（金属製ドラム、フレキシブルコンテナ等）には別の基準がある
・運搬容器は、危険物の類・品名および危険等級によって、認められる材質と最大容積が異なる★

