・液体の危険物は、運搬容器の内容積の98パーセント以下の収納率であって、かつ、55度の温度において漏れないよう十分な空間容積を有して収納すること★
・自然発火性物品は、不活性の気体を封入して密封する等空気と接しないようにすること★
・危険物は、温度変化等により漏れないように運搬容器を密封して収納すること（一定の場合を除く）★
・危険物は、収納する危険物と危険な反応を起こさない等、当該危険物の性質に適合した材質の運搬容器に収納すること★

