・自動車等をタンクの注入口に近づけないこと★
・移動タンク貯蔵所を注入口の付近に停車させ、接地導線で接地する★
・注入中は、移動貯蔵タンクの元弁と注入口の状態を監視する
・荷卸し中は火気を厳禁とし、周囲に人を近づけない

