━━━━━━━━━━━━━━━━━━━━━━
・製造所等の所有者等が、危険物の流出等の事故が発生したときに応急の措置を講じていないと認めるときは、市町村長等はその者に対し、応急の措置を講ずべきことを命ずることができる★
・移動タンク貯蔵所については、事故が発生した場所を管轄する市町村長等が命令を出せる★
・つまり移動タンク貯蔵所は、許可を出した市町村長等だけでなく、走行先の市町村長等からも命令を受けることがあります★

━━━━━━━━━━━━━━━━━━━━━━
