・命令に従わない場合は罰則が適用されます
・使用停止命令や許可の取消しが行われた場合、市町村長等はその旨を公示します★
・命令をしたときも、その旨を公示しなければならない場合があります
・これは近隣住民や取引先に危険を知らせるためです

