・これらは行政手続の期限であり、守らなければ罰則や処分の対象になります
・特に紛らわしいのは「10日以内」「10日前まで」「遅滞なく」の3つです★
・意味を確認しておきましょう。「以内」は行為の後の期間、「前まで」は行為の前の期間です
・「遅滞なく」は正当な理由がない限りすぐに、という意味です★

