・日常語ではどれも似た意味ですが、法律用語としては明確に違います★
・許可は「原則禁止されていることを特別に認める」こと
・承認は「一定の行為を了承する」こと、認可は「私人の行為に効力を与える」こと
・検査は「基準に適合しているか確かめる」ことです
・試験ではこの言葉を入れ替えた選択肢が定番です★

